import random
from typing import List

# Target data type: file bytes for hoedown_buffer_putf
# Generate interesting yet valid byte streams (ASCII-only in byte literals constraint).

_MAX_SIZE = 4096

_MARKDOWN_SNIPPETS: List[bytes] = [
    b"",  # empty file
    b"Hello World\n",
    b"# Header 1\nSome paragraph text.\n\n",
    b"## Header 2\n- item 1\n- item 2\n\n",
    b"1. first\n2. second\n3. third\n\n",
    b"> Quote line\n> continued\n\n",
    b"````\ncode block\nwith lines\n````\n\n",
    b"`inline code` and **bold** and *emphasis* and ~~strike~~\n\n",
    b"[link](https://example.com/path?x=1&y=2) and ![alt](img.png \"title\")\n",
    b"<div class=\"x\">raw <b>HTML</b> & entities &#169; \"quoted\"</div>\n",
    b"---\nkey: value\nflag: true\n---\n\nmeta block above\n\n",
    b"table | head\n----- | -----\ncell1 | cell2\n\n",
    b"- [ ] task unchecked\n- [x] task checked\n\n",
    b"www.example.org short domain\n",
    b"Contact: user.name+tag@example.co.uk\n",
    b"http://example.com/plain\nhttps://sub.domain.example/path#frag\nmailto:user@example.com\n",
    b"Paragraph with escaped chars: & < > \" ' \n",
    b"Setext\n====\n\nSubhead\n----\n\n",
    b"Fenced with lang and attrs:\n```python { .class key=val }\nprint('hello')\n```\n\n",
]

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))

# Helper to encode selected Unicode codepoints into UTF-8 without non-ASCII literals
# We build bytes using integer sequences only.

def _encode_utf8_codepoint(cp: int) -> bytes:
    if cp <= 0x7F:
        return bytes([cp])
    if cp <= 0x7FF:
        return bytes([
            0xC0 | ((cp >> 6) & 0x1F),
            0x80 | (cp & 0x3F),
        ])
    if cp <= 0xFFFF:
        return bytes([
            0xE0 | ((cp >> 12) & 0x0F),
            0x80 | ((cp >> 6) & 0x3F),
            0x80 | (cp & 0x3F),
        ])
    return bytes([
        0xF0 | ((cp >> 18) & 0x07),
        0x80 | ((cp >> 12) & 0x3F),
        0x80 | ((cp >> 6) & 0x3F),
        0x80 | (cp & 0x3F),
    ])

def _unicode_block(rng: random.Random, max_len: int) -> bytes:
    # Build valid UTF-8 from selected ranges, excluding surrogates
    length = rng.randint(1, max(1, max_len // 2))
    ranges = [
        (0x20, 0x7E),      # printable ASCII
        (0x00A0, 0x024F),  # Latin supplement/extended
        (0x0370, 0x03FF),  # Greek
        (0x0400, 0x04FF),  # Cyrillic
        (0x2000, 0x206F),  # Punctuation
        (0x2190, 0x21FF),  # Arrows
        (0x2600, 0x26FF),  # Misc symbols
        (0x1F600, 0x1F64F) # Emojis
    ]
    out = bytearray()
    for _ in range(length):
        lo, hi = rng.choice(ranges)
        cp = rng.randint(lo, hi)
        if 0xD800 <= cp <= 0xDFFF:
            cp = 0x20
        out += _encode_utf8_codepoint(cp)
        if len(out) >= max_len:
            break
    return bytes(out[:max_len])

def _line_endings_mix(rng: random.Random, data: bytes) -> bytes:
    choice = rng.randint(0, 2)
    if choice == 0:
        return data.replace(b"\n", b"\r\n")
    elif choice == 1:
        return data.replace(b"\n", b"\r")
    return data

def _binary_segment(rng: random.Random) -> bytes:
    n = rng.choice([0, 1, 2, 4, 8, 16, 32, 64, 128])
    b = bytearray(_rand_bytes(rng, n))
    for i in range(0, len(b), max(1, len(b)//4 or 1)):
        b[i] = rng.choice([0x00, 0x01, 0x02, 0x09, 0x0A, 0x0D, 0x1B, 0x7F])
    return bytes(b)

def _repeat_block(rng: random.Random, block: bytes, max_total: int) -> bytes:
    if not block:
        return block
    reps = rng.randint(1, min(16, max(1, max_total // max(1, len(block)))))
    return (block * reps)[:max_total]

def _assemble(seed: int) -> bytes:
    rng = random.Random(seed)
    parts: List[bytes] = []

    count = rng.randint(3, 7)
    snippets = rng.sample(_MARKDOWN_SNIPPETS, k=count)
    for snip in snippets:
        pre = b""
        post = b""
        if rng.random() < 0.35:
            pre = _unicode_block(rng, 128)
        if rng.random() < 0.30:
            post = _binary_segment(rng)
        chunk = pre + snip + post
        if rng.random() < 0.5:
            chunk = _line_endings_mix(rng, chunk)
        parts.append(chunk)

    data = b"".join(parts)

    if rng.random() < 0.5 and data:
        data = data + b"\n" + _repeat_block(rng, data[: min(len(data), 256)], max_total=2048)

    extras = []
    if rng.random() < 0.9:
        extras.append(b"Visit http://example.org and https://ex.co?q=1#frag\n")
    if rng.random() < 0.8:
        extras.append(b"Contact: name.surname+tag@sub.example.com\n")
    if rng.random() < 0.6:
        extras.append(b"www.ex.io/path?x=1\n")
    if rng.random() < 0.5:
        extras.append(b"Escape test: <>&\"' and spaces %20\n")

    data += b"".join(extras)

    return data[:_MAX_SIZE]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    mode = rng.randint(0, 4)
    if mode == 0:
        choices = [b"", b"\n", b"\r\n", b" ", b"0\n", b"#\n"]
        return rng.choice(choices)
    elif mode == 1:
        n = rng.randint(0, 1024)
        buf = bytearray(_rand_bytes(rng, n))
        for i in range(0, len(buf), max(1, n // 8 or 1)):
            buf[i] = rng.choice([0x00, 0x0A, 0x0D, 0x09])
        return bytes(buf)
    elif mode == 2:
        block = _unicode_block(rng, 1024)
        block = _line_endings_mix(rng, block + b"\n")
        return block[:_MAX_SIZE]
    elif mode == 3:
        base = b"# H\n\n- a\n- b\n- c\n\n" + b"```\ncode\n```\n\n"
        rep = _repeat_block(rng, base, 3000)
        tail = b"http://a.b/ c@d.e\n"
        return (rep + tail)[:_MAX_SIZE]
    else:
        return _assemble(seed)
